module popcount32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---------------- stage 1 : ten full adders on a_i[29:0] ----------------
wire [9:0] f1a = {a_i[27],a_i[24],a_i[21],a_i[18],a_i[15],a_i[12],a_i[9],a_i[6],a_i[3],a_i[0]};
wire [9:0] f1b = {a_i[28],a_i[25],a_i[22],a_i[19],a_i[16],a_i[13],a_i[10],a_i[7],a_i[4],a_i[1]};
wire [9:0] f1c = {a_i[29],a_i[26],a_i[23],a_i[20],a_i[17],a_i[14],a_i[11],a_i[8],a_i[5],a_i[2]};
wire [9:0] f1x = f1a ^ f1b;
wire [9:0] s1  = f1x ^ f1c;
wire [9:0] c1  = (f1a & f1b) | (f1c & f1x);
// leftovers at weight1 : a_i[30], a_i[31]

// ---------------- stage 2 : weight-1 column (12 bits -> 4 FA) ------------
wire [3:0] f2a = {s1[9],   s1[6], s1[3], s1[0]};
wire [3:0] f2b = {a_i[30], s1[7], s1[4], s1[1]};
wire [3:0] f2c = {a_i[31], s1[8], s1[5], s1[2]};
wire [3:0] f2x = f2a ^ f2b;
wire [3:0] s2  = f2x ^ f2c;          // weight 1
wire [3:0] c2  = (f2a & f2b) | (f2c & f2x);   // weight 2

// ---------------- stage 2 : weight-2 column (10 bits -> 3 FA) ------------
wire [2:0] g2a = {c1[6],c1[3],c1[0]};
wire [2:0] g2b = {c1[7],c1[4],c1[1]};
wire [2:0] g2c = {c1[8],c1[5],c1[2]};
wire [2:0] g2x = g2a ^ g2b;
wire [2:0] t2  = g2x ^ g2c;          // weight 2
wire [2:0] d2  = (g2a & g2b) | (g2c & g2x);   // weight 4
// leftover weight2 : c1[9]

// ---------------- stage 3 ------------------------------------------------
// weight1 : FA(s2[0],s2[1],s2[2]) , leftover s2[3]
wire x3   = s2[0] ^ s2[1];
wire s3   = x3 ^ s2[2];                          // weight1 row A
wire c3   = (s2[0] & s2[1]) | (s2[2] & x3);      // weight2

// weight2 : FA(t2), FA(c2[2:0]), HA(c1[9],c2[3])
wire xa   = t2[0] ^ t2[1];
wire u3_0 = xa ^ t2[2];
wire v3_0 = (t2[0] & t2[1]) | (t2[2] & xa);
wire xb   = c2[0] ^ c2[1];
wire u3_1 = xb ^ c2[2];
wire v3_1 = (c2[0] & c2[1]) | (c2[2] & xb);
wire u3_2 = c1[9] ^ c2[3];
wire v3_2 = c1[9] & c2[3];

// weight4 : FA(d2)
wire xc    = d2[0] ^ d2[1];
wire s3w2  = xc ^ d2[2];                         // weight4
wire c3w2  = (d2[0] & d2[1]) | (d2[2] & xc);     // weight8

// ---------------- stage 4 ------------------------------------------------
wire xd   = u3_0 ^ u3_1;
wire p4a  = xd ^ u3_2;                           // weight2 row A
wire q4a  = (u3_0 & u3_1) | (u3_2 & xd);         // weight4

wire xe   = s3w2 ^ v3_0;
wire p4b  = xe ^ v3_1;                           // weight4
wire q4b  = (s3w2 & v3_0) | (v3_1 & xe);         // weight8

// ---------------- stage 5 ------------------------------------------------
wire xf   = p4b ^ v3_2;
wire p5   = xf ^ q4a;                            // weight4 row A
wire q5   = (p4b & v3_2) | (q4a & xf);           // weight8 row B

wire h5   = c3w2 ^ q4b;                          // weight8 row A
wire g5   = c3w2 & q4b;                          // weight16 row A

// ---------------- final carry-lookahead add of the two rows --------------
// A = {g5, h5, p5, p4a, s3}   B = {0, q5, 0, c3, s2[3]}
wire k0  = s3 & s2[3];
wire pp1 = p4a ^ c3;
wire gg1 = p4a & c3;
wire k1  = gg1 | (pp1 & k0);
wire k2  = p5 & k1;
wire pp3 = h5 ^ q5;
wire gg3 = h5 & q5;
wire k3  = gg3 | (pp3 & k2);

wire [5:0] total_0;
assign total_0[0] = s3  ^ s2[3];
assign total_0[1] = pp1 ^ k0;
assign total_0[2] = p5  ^ k1;
assign total_0[3] = pp3 ^ k2;
assign total_0[4] = g5  ^ k3;
assign total_0[5] = g5  & k3;

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= total_0;
    end
end
endmodule

module popcount32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ================= stage A : 10 full adders + 1 half adder ===============
wire [9:0] A0 = {a_i[27],a_i[24],a_i[21],a_i[18],a_i[15],a_i[12],a_i[9],a_i[6],a_i[3],a_i[0]};
wire [9:0] B0 = {a_i[28],a_i[25],a_i[22],a_i[19],a_i[16],a_i[13],a_i[10],a_i[7],a_i[4],a_i[1]};
wire [9:0] D0 = {a_i[29],a_i[26],a_i[23],a_i[20],a_i[17],a_i[14],a_i[11],a_i[8],a_i[5],a_i[2]};
wire [9:0] X0 = A0 ^ B0;
wire [9:0] S  = X0 ^ D0;                 // weight 1, t=2
wire [9:0] C  = (A0 & B0) | (D0 & X0);   // weight 2, t=2
wire Sh = a_i[30] ^ a_i[31];             // weight 1, t=1
wire Ch = a_i[30] & a_i[31];             // weight 2, t=1

// ================= stage B : column weight-1  (11 bits -> 2 rows) ========
wire xu0 = S[0] ^ S[1];
wire u0  = xu0 ^ S[2];
wire k0  = (S[0] & S[1]) | (S[2] & xu0);
wire xu1 = S[3] ^ S[4];
wire u1  = xu1 ^ S[5];
wire k1  = (S[3] & S[4]) | (S[5] & xu1);
wire xu2 = S[6] ^ S[7];
wire u2  = xu2 ^ S[8];
wire k2  = (S[6] & S[7]) | (S[8] & xu2);
wire xu3 = Sh ^ S[9];
wire u3  = xu3 ^ u0;
wire k3  = (Sh & S[9]) | (u0 & xu3);
wire v0  = u1 ^ u2;
wire k4  = u1 & u2;
// weight-1 rows : v0 , u3

// ================= stage C : column weight-2  (16 bits -> 2 rows) ========
wire xm0 = C[0] ^ C[1];
wire m0  = xm0 ^ Ch;
wire n0  = (C[0] & C[1]) | (Ch & xm0);
wire xm1 = C[2] ^ C[3];
wire m1  = xm1 ^ C[4];
wire n1  = (C[2] & C[3]) | (C[4] & xm1);
wire xm2 = C[5] ^ C[6];
wire m2  = xm2 ^ C[7];
wire n2  = (C[5] & C[6]) | (C[7] & xm2);
wire xm3 = C[8] ^ C[9];
wire m3  = xm3 ^ m0;
wire n3  = (C[8] & C[9]) | (m0 & xm3);
wire xm4 = m1 ^ m2;
wire m4  = xm4 ^ k0;
wire n4  = (m1 & m2) | (k0 & xm4);
wire xm5 = k1 ^ k2;
wire m5  = xm5 ^ k3;
wire n5  = (k1 & k2) | (k3 & xm5);
wire xm6 = k4 ^ m3;
wire m6  = xm6 ^ m4;
wire n6  = (k4 & m3) | (m4 & xm6);
// weight-2 rows : m5 , m6

// ================= stage D : column weight-4  (7 bits -> 2 rows) =========
wire xq0 = n0 ^ n1;
wire q0  = xq0 ^ n2;
wire r0  = (n0 & n1) | (n2 & xq0);
wire q1  = n3 ^ n4;
wire r1  = n3 & n4;
wire xq2 = q0 ^ n5;
wire q2  = xq2 ^ q1;
wire r2  = (q0 & n5) | (q1 & xq2);
// weight-4 rows : n6 , q2

// ================= stage E : column weight-8  (3 bits -> 2 rows) =========
wire w0 = r0 ^ r1;
wire e0 = r0 & r1;
// weight-8 rows : w0 , r2   ; weight-16 row : e0

// ================= final 5-bit carry-lookahead addition ==================
wire p0 = v0 ^ u3;
wire g0 = v0 & u3;
wire p1 = m5 ^ m6;
wire g1 = m5 & m6;
wire p2 = n6 ^ q2;
wire g2 = n6 & q2;
wire p3 = w0 ^ r2;
wire g3 = w0 & r2;
wire p4 = e0;

wire c1 = g0;
wire c2 = g1 | (p1 & c1);
wire c3 = g2 | (p2 & c2);
wire c4 = g3 | (p3 & c3);

wire [5:0] total_0;
assign total_0[0] = p0;
assign total_0[1] = p1 ^ c1;
assign total_0[2] = p2 ^ c2;
assign total_0[3] = p3 ^ c3;
assign total_0[4] = p4 ^ c4;
assign total_0[5] = p4 & c4;

// ================= output registers ======================================
wire       en   = rst_n & valid_i;
wire [5:0] hold = y_o & {6{rst_n}};

always @(posedge clk) begin
    valid_o <= en;
    y_o     <= en ? total_0 : hold;
end
endmodule

module popcount32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ============ eight 4-bit counters : B2 B1 B0 = popcount(a[4j+3:4j]) =====
wire [7:0] ua = {a_i[28],a_i[24],a_i[20],a_i[16],a_i[12],a_i[8], a_i[4],a_i[0]};
wire [7:0] ub = {a_i[29],a_i[25],a_i[21],a_i[17],a_i[13],a_i[9], a_i[5],a_i[1]};
wire [7:0] uc = {a_i[30],a_i[26],a_i[22],a_i[18],a_i[14],a_i[10],a_i[6],a_i[2]};
wire [7:0] ud = {a_i[31],a_i[27],a_i[23],a_i[19],a_i[15],a_i[11],a_i[7],a_i[3]};
wire [7:0] U = ua ^ ub;
wire [7:0] V = ua & ub;
wire [7:0] W = uc ^ ud;
wire [7:0] Z = uc & ud;
wire [7:0] B0 = U ^ W;                  // weight 1
wire [7:0] B1 = (V ^ Z) ^ (U & W);      // weight 2
wire [7:0] B2 = V & Z;                  // weight 4

// ================= column weight-1 : 8 bits -> 2 rows ====================
wire x00 = B0[0] ^ B0[1];
wire s00 = x00 ^ B0[2];
wire c00 = (B0[0] & B0[1]) | (B0[2] & x00);
wire x01 = B0[3] ^ B0[4];
wire s01 = x01 ^ B0[5];
wire c01 = (B0[3] & B0[4]) | (B0[5] & x01);
wire x02 = B0[6] ^ B0[7];
wire s02 = x02 ^ s00;
wire c02 = (B0[6] & B0[7]) | (s00 & x02);

// ================= column weight-2 : 11 bits -> 2 rows ===================
wire x10 = B1[0] ^ B1[1];
wire s10 = x10 ^ B1[2];
wire c10 = (B1[0] & B1[1]) | (B1[2] & x10);
wire x11 = B1[3] ^ B1[4];
wire s11 = x11 ^ B1[5];
wire c11 = (B1[3] & B1[4]) | (B1[5] & x11);
wire x12 = B1[6] ^ B1[7];
wire s12 = x12 ^ c00;
wire c12 = (B1[6] & B1[7]) | (c00 & x12);
wire x13 = c01 ^ s10;
wire s13 = x13 ^ c02;
wire c13 = (c01 & s10) | (c02 & x13);
wire s14 = s11 ^ s12;
wire c14 = s11 & s12;

// ================= column weight-4 : 13 bits -> 2 rows ===================
wire x20 = B2[0] ^ B2[1];
wire s20 = x20 ^ B2[2];
wire c20 = (B2[0] & B2[1]) | (B2[2] & x20);
wire x21 = B2[3] ^ B2[4];
wire s21 = x21 ^ B2[5];
wire c21 = (B2[3] & B2[4]) | (B2[5] & x21);
wire x22 = B2[6] ^ B2[7];
wire s22 = x22 ^ s20;
wire c22 = (B2[6] & B2[7]) | (s20 & x22);
wire x23 = s21 ^ s22;
wire s23 = x23 ^ c10;
wire c23 = (s21 & s22) | (c10 & x23);
wire x24 = c11 ^ c12;
wire s24 = x24 ^ c14;
wire c24 = (c11 & c12) | (c14 & x24);
wire s25 = s23 ^ c13;
wire c25 = s23 & c13;

// ================= column weight-8 : 6 bits -> 2 rows ====================
wire x30 = c20 ^ c21;
wire s30 = x30 ^ c22;
wire c30 = (c20 & c21) | (c22 & x30);
wire x31 = s30 ^ c23;
wire s31 = x31 ^ c24;
wire c31 = (s30 & c23) | (c24 & x31);

// ================= final 5-position carry propagate =====================
wire p0 = s01 ^ s02;
wire g0 = s01 & s02;
wire p1 = s13 ^ s14;
wire g1 = s13 & s14;
wire p2 = s25 ^ s24;
wire g2 = s25 & s24;
wire p3 = s31 ^ c25;
wire g3 = s31 & c25;
wire p4 = c30 ^ c31;
wire g4 = c30 & c31;

wire k1 = g0;
wire k2 = g1 | (p1 & k1);
wire k3 = g2 | (p2 & k2);
wire k4 = g3 | (p3 & k3);
wire k5 = g4 | (p4 & k4);

wire [5:0] total_0;
assign total_0[0] = p0;
assign total_0[1] = p1 ^ k1;
assign total_0[2] = p2 ^ k2;
assign total_0[3] = p3 ^ k3;
assign total_0[4] = p4 ^ k4;
assign total_0[5] = k5;

always @(posedge clk) begin
    if (!rst_n) begin
        valid_o <= 1'b0;
        y_o <= 6'd0;
    end else begin
        valid_o <= valid_i;
        if (valid_i)
            y_o <= total_0;
    end
end
endmodule

module popcount32 (
    input wire clk,
    input wire rst_n,
    input wire valid_i,
    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

// ---------------- stage 1 : ten full adders on a_i[29:0] ----------------
wire [9:0] f1a = {a_i[27],a_i[24],a_i[21],a_i[18],a_i[15],a_i[12],a_i[9],a_i[6],a_i[3],a_i[0]};
wire [9:0] f1b = {a_i[28],a_i[25],a_i[22],a_i[19],a_i[16],a_i[13],a_i[10],a_i[7],a_i[4],a_i[1]};
wire [9:0] f1c = {a_i[29],a_i[26],a_i[23],a_i[20],a_i[17],a_i[14],a_i[11],a_i[8],a_i[5],a_i[2]};
wire [9:0] f1x = f1a ^ f1b;
wire [9:0] s1  = f1x ^ f1c;
wire [9:0] c1  = (f1a & f1b) | (f1c & f1x);
// leftovers at weight1 : a_i[30], a_i[31]

// ---------------- stage 2 : weight-1 column (12 bits -> 4 FA) ------------
wire [3:0] f2a = {s1[9],   s1[6], s1[3], s1[0]};
wire [3:0] f2b = {a_i[30], s1[7], s1[4], s1[1]};
wire [3:0] f2c = {a_i[31], s1[8], s1[5], s1[2]};
wire [3:0] f2x = f2a ^ f2b;
wire [3:0] s2  = f2x ^ f2c;
wire [3:0] c2  = (f2a & f2b) | (f2c & f2x);

// ---------------- stage 2 : weight-2 column (10 bits -> 3 FA) ------------
wire [2:0] g2a = {c1[6],c1[3],c1[0]};
wire [2:0] g2b = {c1[7],c1[4],c1[1]};
wire [2:0] g2c = {c1[8],c1[5],c1[2]};
wire [2:0] g2x = g2a ^ g2b;
wire [2:0] t2  = g2x ^ g2c;
wire [2:0] d2  = (g2a & g2b) | (g2c & g2x);

// ---------------- stage 3 ------------------------------------------------
wire x3   = s2[0] ^ s2[1];
wire s3   = x3 ^ s2[2];
wire c3   = (s2[0] & s2[1]) | (s2[2] & x3);

wire xa   = t2[0] ^ t2[1];
wire u3_0 = xa ^ t2[2];
wire v3_0 = (t2[0] & t2[1]) | (t2[2] & xa);
wire xb   = c2[0] ^ c2[1];
wire u3_1 = xb ^ c2[2];
wire v3_1 = (c2[0] & c2[1]) | (c2[2] & xb);
wire u3_2 = c1[9] ^ c2[3];
wire v3_2 = c1[9] & c2[3];

wire xc    = d2[0] ^ d2[1];
wire s3w2  = xc ^ d2[2];
wire c3w2  = (d2[0] & d2[1]) | (d2[2] & xc);

// ---------------- stage 4 ------------------------------------------------
wire xd   = u3_0 ^ u3_1;
wire p4a  = xd ^ u3_2;
wire q4a  = (u3_0 & u3_1) | (u3_2 & xd);

wire xe   = s3w2 ^ v3_0;
wire p4b  = xe ^ v3_1;
wire q4b  = (s3w2 & v3_0) | (v3_1 & xe);

// ---------------- stage 5 ------------------------------------------------
wire xf   = p4b ^ v3_2;
wire p5   = xf ^ q4a;
wire q5   = (p4b & v3_2) | (q4a & xf);

wire h5   = c3w2 ^ q4b;
wire g5   = c3w2 & q4b;

// ---------------- final carry-lookahead add of the two rows --------------
wire k0  = s3 & s2[3];
wire pp1 = p4a ^ c3;
wire gg1 = p4a & c3;
wire k1  = gg1 | (pp1 & k0);
wire k2  = p5 & k1;
wire pp3 = h5 ^ q5;
wire gg3 = h5 & q5;
wire k3  = gg3 | (pp3 & k2);

wire [5:0] total_0;
assign total_0[0] = s3  ^ s2[3];
assign total_0[1] = pp1 ^ k0;
assign total_0[2] = p5  ^ k1;
assign total_0[3] = pp3 ^ k2;
assign total_0[4] = g5  ^ k3;
assign total_0[5] = g5  & k3;

// ---------------- output registers --------------------------------------
wire       en   = rst_n & valid_i;
wire [5:0] hold = y_o & {6{rst_n}};

always @(posedge clk) begin
    valid_o <= en;
    y_o     <= en ? total_0 : hold;
end
endmodule
